/**
 * A PEDIDO (2026-10-08, "Compartilhamento social", Fase 1) — pedaços
 * puramente visuais extraídos de `app/u/[username]/opengraph-image.tsx`
 * (cores da marca, logo em base64, selo de verificação pro OG), SEM
 * MODIFICAR aquele arquivo (instrução explícita: a implementação do
 * perfil compartilhável não deve ser tocada). Reaproveitados aqui
 * porque o card de review (`app/r/[reviewId]/opengraph-image.tsx`)
 * precisa exatamente da mesma identidade visual — duplicar via cópia
 * seria ~13KB de base64 repetido à toa.
 */

export const BRAND = {
  bg: "#0B0E14",
  surface: "#131826",
  border: "#262D40",
  primary: "#E8A33D",
  muted: "#8C93A8",
  text: "#F4F1E8",
};

export const SEENLIST_MARK_BASE64 =
  "";

/**
 * Arquivos reais da fonte Plus Jakarta Sans (Bold e ExtraBold),
 * baixados direto do Google Fonts e embutidos aqui como base64 —
 * removendo a dependência da API ao vivo do Google Fonts
 * (`loadGoogleFont`/`loadGoogleFontSafe`) para o card de perfil.
 *
 * CAUSA RAIZ (2026-10-08) que motivou essa troca: a API css2 do
 * Google Fonts, pra essa família/pesos, estava servindo um arquivo
 * de ~1.6KB (corrompido/inválido), fazendo o satori renderizar o
 * texto com um peso de fonte visualmente errado ("mais black" do
 * que o esperado). Em vez de continuar dependendo de uma API externa
 * que já quebrou esse fluxo 3 vezes em produção, os bytes reais da
 * fonte (baixados manualmente, tamanho verificado: 94.772 bytes o
 * Bold, 94.780 bytes o ExtraBold) ficam fixos no código — sem
 * variação possível, sem chamada de rede, sem risco de resposta
 * inválida.
 */
export const PLUS_JAKARTA_SANS_BOLD_BASE64 =
  "";

export const PLUS_JAKARTA_SANS_EXTRABOLD_BASE64 =
  "";

/**
 * Decodifica os base64 das fontes acima pra `ArrayBuffer` — formato
 * que `ImageResponse`/satori espera em `fonts[].data`. `atob` existe
 * no Edge Runtime do Next.js (não é Node puro), então não precisa de
 * `Buffer`. Compartilhado entre o card de perfil e o card de review
 * — os dois embutem a mesma fonte local (ver comentário acima),
 * removendo a dependência da API ao vivo do Google Fonts nos dois.
 */
export function decodeBase64Font(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}

